files.src/SeriesParallel.st:
PROGRAM SeriesParallel
VAR_INPUT Auto AT %I0.0 : BOOL; Ready AT %I0.1 : BOOL; DoorOpen AT %I0.2 : BOOL; Overheat AT %I0.3 : BOOL; END_VAR
VAR_OUTPUT RunLamp AT %Q0.0 : BOOL; Horn AT %Q0.1 : BOOL; END_VAR
RunLamp := Auto AND Ready;
Horn := DoorOpen OR Overheat;
END_PROGRAM

